  $('#app').innerHTML = `<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><img src="/icon.svg" alt=""/><div><div class="brand-name">RTM<span> IT</span></div><div class="brand-sub">Raqamli boshqaruv tizimi</div></div></a><div class="workspace"><span class="workspace-icon">${icon('building', 17)}</span><div><strong>Nukus filiali</strong><span class="muted small" style="font-size:10px">O‘zDJTSU</span></div>${icon('down', 13)}</div><div class="nav-title">ISH MAYDONI</div><nav class="nav" aria-label="Asosiy menyu">${menu.map(([id, title, ico]) => `<a href="#${id}" class="nav-item" data-nav="${id}">${icon(ico, 17)}<span>${title}</span>${id === 'tickets' ? '<span id="nav-ticket-count" class="nav-count">—</span>' : ''}</a>`).join('')}</nav><div class="nav-title secondary">BOSHQARUV</div><nav class="nav" aria-label="Tizim boshqaruvi">${(elevated() ? [['users', 'Xodimlar va bo‘limlar', 'users']] : []).concat(myRole('superadmin') ? [['audit', 'Tizim jurnali', 'shield']] : []).concat([['settings', 'Sozlamalar', 'settings']]).map(([id, title, ico]) => `<a href="#${id}" class="nav-item" data-nav="${id}">${icon(ico, 17)}${title}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="server-status"><span class="status-light"></span><div><strong>Lokal server faol</strong><p>Ichki tarmoq · Internet talab etilmaydi</p></div></div><div class="profile"><span class="avatar">${e(initials(S.user.name))}</span><div><strong>${e(S.user.name)}</strong><small>${e(roleLabel())}</small></div><button data-action="logout" class="logout" title="Chiqish" aria-label="Tizimdan chiqish">${icon('logout', 16)}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu" data-action="menu" aria-label="Menyu">${icon('menu')}</button>${icon('grid', 14)}<span>Ish maydoni</span><span>/</span><strong id="breadcrumb">Boshqaruv paneli</strong></div><div class="top-actions"><form class="top-search" id="global-search">${icon('search', 14)}<input name="q" placeholder="Tezkor qidiruv…" aria-label="Murojaatni qidirish"/><span class="keycap">↵</span></form>${S.mode === 'test' ? '<span class="test-pill">TEST REJIMI</span>' : ''}<button class="bell" data-action="notifications" title="Bildirishnomalar" aria-label="Bildirishnomalar">${icon('bell', 19)}<span class="dot"></span></button><span class="top-divider"></span><span class="avatar">${e(initials(S.user.name))}</span></div></header><div id="connection"></div><div class="content"><div id="page"></div><footer class="footer"><span>© 2026 RTM IT · Nukus filiali</span><span>${icon('shield', 11)} Xavfsiz ichki tarmoq <span>·</span> v0.3.0</span></footer></div></main></div>`;
  $('#global-search').onsubmit = event => { event.preventDefault(); S.filters = { q: new FormData(event.target).get('q') }; go('tickets'); };
