    if(a==='ticket-status')openModal('Holat: '+label(button.dataset.status),field('comment',button.dataset.status==='completed'?'Bajarilgan ish haqida izoh *':'Izoh','textarea','','minlength="5" '+(button.dataset.status==='completed'?'required':'')),async values=>{await api('/tickets/'+S.ticket.id,{method:'PATCH',body:{...values,status:button.dataset.status}});toast('Murojaat holati yangilandi');await route();});
    if(a==='ticket-comment')openModal('Izoh qo‘shish',field('comment','Izoh *','textarea','','required minlength="3" maxlength="6000"'),async values=>{await api('/tickets/'+S.ticket.id,{method:'PATCH',body:values});toast('Izoh saqlandi');await route();});
    if(a==='ticket-rate')openModal('Xizmatni baholash',select('rating','Baho',[[5,'★★★★★ — A’lo'],[4,'★★★★ — Yaxshi'],[3,'★★★ — Qoniqarli'],[2,'★★ — Qoniqarsiz'],[1,'★ — Yomon']],S.ticket.rating||5,''),async values=>{await api('/tickets/'+S.ticket.id,{method:'PATCH',body:values});toast('Baho saqlandi');await route();});
    if(a==='attach')openModal('Fayl biriktirish',field('file','PNG, JPEG yoki PDF (5 MB gacha)','file','','required accept="image/png,image/jpeg,application/pdf"'),async (values,form)=>{const data=new FormData(form);await api(`/tickets/${S.ticket.id}/attachments`,{method:'POST',body:data});toast('Fayl biriktirildi');await route();});
    if(a==='device-status')openModal('Texnik holatni yangilash',select('status','Holat',['warehouse','in_use','reserve','diagnostics','repair','faulty',...(elevated()?['retired']:[])],S.device.status,'')+field('specs','Texnik parametrlar','textarea',S.device.specs)+field('os','Operatsion tizim','text',S.device.os)+field('ip','IP manzil','text',S.device.ip)+'<label class="checkbox"><input type="checkbox" name="confirm"/>Hisobdan chiqarishni tasdiqlayman (faqat bo‘sh qurilma uchun).</label>',async values=>{await api('/devices/'+S.device.id,{method:'PATCH',body:{...values,confirm:Boolean(values.confirm)}});toast('Qurilma yangilandi');await route();});
